import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Try different Collection types!
        List<String> list = new ArrayList<>(List.of("Banana", "Apple", "Mango", "Cherry"));

        // Sort
        Collections.sort(list);
        System.out.println("Sorted: " + list);

        // Java 21 — getFirst / getLast
        System.out.println("First: " + list.getFirst());
        System.out.println("Last:  " + list.getLast());

        // Convert to Set — removes duplicates
        list.add("Apple");
        Set<String> uniqueFruits = new LinkedHashSet<>(list);
        System.out.println("Unique: " + uniqueFruits);
    }
}

